export type PlayerIcon = keyof typeof icons;
export function playerIcon(name: PlayerIcon): SVGSVGElement {
  const svg = new DOMParser().parseFromString(icons[name], 'image/svg+xml').documentElement;
  const node = document.importNode(svg, true) as unknown as SVGSVGElement;
  node.setAttribute('aria-hidden', 'true'); node.setAttribute('focusable', 'false');
  node.setAttribute('width', '24'); node.setAttribute('height', '24');
  return node;
}
export function setPlayerIcon(button: HTMLElement, name: PlayerIcon): void {
  if (button.dataset.playerIcon === name) return;
  button.dataset.playerIcon = name; button.replaceChildren(playerIcon(name));
}
